package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.Fragment;import com.google.android.material.button.MaterialButton;import java.util.*;
public class PrepositionFragment extends Fragment{
 private List<PrepositionExercise> qs;private int index=0,correct=0;private ProgressStore progress;private TextView stats,sentence,zh,feedback;private final List<MaterialButton> answers=new ArrayList<>();private MaterialButton next;private long started;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_prepositions,c,false);progress=new ProgressStore(requireContext());PrepositionRepository repo=new PrepositionRepository(requireContext());qs=repo.session(progress.sessionMinutes()>=30?14:8);stats=v.findViewById(R.id.text_prep_stats);sentence=v.findViewById(R.id.text_prep_sentence);zh=v.findViewById(R.id.text_prep_zh);feedback=v.findViewById(R.id.text_prep_feedback);answers.add(v.findViewById(R.id.prep_answer_1));answers.add(v.findViewById(R.id.prep_answer_2));answers.add(v.findViewById(R.id.prep_answer_3));answers.add(v.findViewById(R.id.prep_answer_4));next=v.findViewById(R.id.button_prep_next);next.setOnClickListener(x->{index++;show();});show();return v;}
 private void show(){feedback.setText("");next.setVisibility(View.GONE);if(index>=qs.size()){sentence.setText("本轮完成");zh.setText("介词专项正确 "+correct+" / "+qs.size()+" · "+(qs.isEmpty()?0:correct*100/qs.size())+"%");for(MaterialButton b:answers)b.setVisibility(View.GONE);return;}PrepositionExercise q=qs.get(index);stats.setText("第 "+(index+1)+" / "+qs.size()+" 题 · 本轮正确 "+correct);sentence.setText(q.sentence);zh.setText(q.chinese);for(int n=0;n<answers.size();n++){MaterialButton b=answers.get(n);if(n<q.options.size()){String opt=q.options.get(n);b.setVisibility(View.VISIBLE);b.setEnabled(true);b.setText(opt);b.setOnClickListener(v->answer(opt));}else b.setVisibility(View.GONE);}started=System.currentTimeMillis();}
 private void answer(String choice){PrepositionExercise q=qs.get(index);boolean ok=q.answer.equals(choice);if(ok)correct++;long ms=System.currentTimeMillis()-started;progress.recordGrammarResult("prepositions",ok,ms);progress.recordAuxiliaryResult("preposition",ok,ms);feedback.setText((ok?"✓ 正确":"✗ 正确答案："+q.answer)+"\n"+q.explanation);feedback.setTextColor(ContextCompat.getColor(requireContext(),ok?R.color.success:R.color.error));for(MaterialButton b:answers)b.setEnabled(false);next.setVisibility(View.VISIBLE);}
}
